from funcy import flip
r=flip({'a':1,'b':2}); print('flipped',r)
assert r=={1:'a',2:'b'}

from funcy import select_keys
r=select_keys(lambda key:key.startswith('a'), {'a':1,'b':2}); print('selected',r)
assert r=={'a':1}

from funcy import project
r=project({'a':1,'b':2}, ['a','missing']); print('projected',r)
assert r=={'a':1}

from funcy import zip_dicts
r=dict(zip_dicts({'a':1,'b':2},{'a':3,'c':4})); print('joined',r)
assert r=={'a':(1,3)}
assert dict(zip_dicts({'a':1}))=={'a':(1,)}

from funcy import group_by
r=group_by(lambda value:value%2,[1,2,3,4]);print('grouped',dict(r))
assert r=={0:[2,4],1:[1,3]}

from funcy import group_values
r=group_values([('a',1),('a',1),('b',3),('a',2)]);print('grouped_values',dict(r))
assert r=={'a':[1,1,2],'b':[3]}

from funcy import count_reps
r=count_reps('ababa');print('counts',dict(r))
assert r=={'a':3,'b':2}

from funcy import join_with
r=join_with(list,[{'a':1},{'a':2,'b':3}],strict=True);print('aggregated',r)
assert r=={'a':[1,2],'b':[3]}

from funcy import walk
r=walk(lambda pair:(pair[0].upper(),pair[1]+1),{'a':1,'b':2});print('walked',r)
assert r=={'A':2,'B':3}
